const mediaFilters=document.querySelector('.media-filters'),mediaCards=Array.from(document.querySelectorAll('.media-card')),mediaChips=Array.from(document.querySelectorAll('[data-media-filter]'));
mediaFilters.hidden=false;
function filterMedia(category){if(!mediaChips.some(b=>b.dataset.mediaFilter===category))category='all';let visible=0;mediaCards.forEach(card=>{card.hidden=category!=='all'&&card.dataset.category!==category;if(!card.hidden)visible++});mediaChips.forEach(button=>{const selected=button.dataset.mediaFilter===category;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected))});document.querySelector('#media-count').textContent=`${visible} daripada ${mediaCards.length} rekod galeri`;const url=new URL(location.href);category==='all'?url.searchParams.delete('kategori'):url.searchParams.set('kategori',category);history.replaceState(null,'',url)}
mediaChips.forEach(button=>button.addEventListener('click',()=>filterMedia(button.dataset.mediaFilter)));filterMedia(new URLSearchParams(location.search).get('kategori')||'all');addEventListener('popstate',()=>filterMedia(new URLSearchParams(location.search).get('kategori')||'all'));
